+// Recognizes a credential by its canonical name form only.
+const CANONICAL_CREDENTIAL_NAME = /^token$/;
+
+export function redactCredentials(fields: Record<string, string>): Record<string, string> {
+  return Object.fromEntries(
+    Object.entries(fields).map(([name, value]) => [
+      name,
+      CANONICAL_CREDENTIAL_NAME.test(name) ? "<redacted>" : value,
+    ]),
+  );
+}
+
+export function describeRequest(authToken: string): Record<string, string> {
+  return redactCredentials({ authToken });
+}
+
